import { useState } from 'react';
import { productApi } from '../services/api';
import ProductCard from '../components/ProductCard';

function AiRecommendationsPage() {
  const [form, setForm] = useState({ query: 'laptop', usage: 'study', budget: 150000, preferredBrand: '' });
  const [products, setProducts] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setMessage('');
    try {
      const data = await productApi.getRecommendations(form);
      setProducts(data.products || []);
      setMessage(data.source === 'python-ai' ? 'Python AI ranked these products for your use case.' : data.message || 'Fallback recommendations loaded.');
    } catch {
      setMessage('Unable to load AI recommendations. Please check Node and Python backends.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="container section">
      <div className="section-header">
        <div>
          <span className="eyebrow">Python AI recommendations</span>
          <h1 className="title">Smart product suggestions</h1>
          <p className="subtitle">The Node backend fetches live product data, then sends normalized products to Python AI for ranking.</p>
        </div>
      </div>
      <form className="card" style={{ padding: 20, display: 'grid', gridTemplateColumns: 'repeat(5, minmax(0, 1fr))', gap: 12, marginBottom: 24 }} onSubmit={submit}>
        <input value={form.query} onChange={(e) => setForm({ ...form, query: e.target.value })} placeholder="Product query" />
        <select value={form.usage} onChange={(e) => setForm({ ...form, usage: e.target.value })}>
          <option value="study">Study</option>
          <option value="gaming">Gaming</option>
          <option value="office">Office</option>
          <option value="creator">Creator</option>
          <option value="mobile">Mobile</option>
        </select>
        <input type="number" value={form.budget} onChange={(e) => setForm({ ...form, budget: e.target.value })} placeholder="Budget" />
        <input value={form.preferredBrand} onChange={(e) => setForm({ ...form, preferredBrand: e.target.value })} placeholder="Preferred brand" />
        <button className="btn btn-primary" type="submit">Recommend</button>
      </form>
      {message && <div className="badge" style={{ marginBottom: 18 }}>{message}</div>}
      {loading && <div className="loading-skeleton" style={{ height: 280 }} />}
      {!loading && products.length > 0 && <div className="grid grid-4">{products.map((product) => <ProductCard key={product.id || product.productId} product={product} />)}</div>}
    </section>
  );
}

export default AiRecommendationsPage;
